solution:
static int[] duplicate(int[] a) {
    int[] out = new int[a.length];
    for (int i = 0; i < a.length; i++) {
        out[i] = a[i];
    }
    return out;
}

static boolean sharesStorageWith(int[] a, int[] b) {
    if (a == null || b == null) return false;
    return a == b;
}

static void bumpFirst(int[] a) {
    a[0] = a[0] + 1;
}
